insert into public.role_permissions(role_id,permission_code) select r.id,g.permission_code from grants g join public.roles r on r.code=g.role_code on conflict do nothing;
alter table public.operational_sales add column if not exists customer_id uuid references public.customers(id);
alter table public.operational_sales add column if not exists demand_request_id uuid references public.clinical_demand_requests(id);
alter table public.operational_sales add column if not exists invoice_date date;
alter table public.operational_sales add column if not exists payment_due_date date;
alter table public.dispatches add column if not exists demand_request_id uuid references public.clinical_demand_requests(id);
alter table public.clinical_demand_requests add column if not exists fulfilled_dispatch_id uuid references public.dispatches(id);
alter table public.clinical_demand_requests add column if not exists fulfilled_at timestamptz;
alter table public.donor_campaigns add column if not exists planned_cost numeric(14,2) not null default 0;
alter table public.donor_campaigns add column if not exists actual_cost numeric(14,2) not null default 0;
alter table public.donor_campaigns add column if not exists contacts_reached integer not null default 0;
create table if not exists public.customer_payments(id uuid primary key default gen_random_uuid(),branch_id uuid references public.branches(id),customer_id uuid not null references public.customers(id),sale_id uuid references public.operational_sales(id),payment_date date not null default current_date,amount numeric(14,2) not null check(amount>0),payment_method text not null default 'TRANSFERENCIA',reference text,notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create index if not exists idx_customer_payments_sale_date on public.customer_payments(sale_id,payment_date desc);create index if not exists idx_customer_payments_customer_date on public.customer_payments(customer_id,payment_date desc);create index if not exists idx_customer_payments_branch_date on public.customer_payments(branch_id,payment_date desc);alter table public.customer_payments enable row level security;
create table if not exists public.inventory_loss_events(id uuid primary key default gen_random_uuid(),branch_id uuid not null references public.branches(id),blood_inventory_unit_id uuid references public.blood_inventory_units(id),product_id uuid references public.products(id),event_date date not null default current_date,loss_type text not null check(loss_type in ('VENCIMIENTO','DESCARTE','ROTURA','CADENA_FRIO','CALIDAD','OTRO')),quantity numeric(12,2) not null default 1 check(quantity>0),unit_cost numeric(14,2) not null default 0,estimated_loss numeric(14,2) generated always as (quantity*unit_cost) stored,reason text not null,linked_action_id uuid references public.integrated_actions(id),created_by uuid references auth.users(id),created_at timestamptz not null default now());
create index if not exists idx_inventory_loss_branch_date on public.inventory_loss_events(branch_id,event_date desc);create index if not exists idx_inventory_loss_product on public.inventory_loss_events(product_id,event_date desc);alter table public.inventory_loss_events enable row level security;
create table if not exists public.medical_referrers(id uuid primary key default gen_random_uuid(),branch_id uuid references public.branches(id),referrer_code text not null unique,full_name text not null,specialty text,organization text,phone text,email text,city text,status text not null default 'ACTIVO' check(status in ('ACTIVO','INACTIVO','PROSPECTO')),notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists idx_medical_referrers_branch_status on public.medical_referrers(branch_id,status);alter table public.medical_referrers enable row level security;
create table if not exists public.medical_referral_events(id uuid primary key default gen_random_uuid(),referrer_id uuid not null references public.medical_referrers(id),branch_id uuid references public.branches(id),customer_id uuid references public.customers(id),demand_request_id uuid references public.clinical_demand_requests(id),referral_date date not null default current_date,channel text not null default 'MEDICO',estimated_units integer not null default 0,status text not null default 'REFERIDO' check(status in ('REFERIDO','CONTACTADO','CONVERTIDO','NO_CONVERTIDO')),notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create index if not exists idx_medical_referral_referrer_date on public.medical_referral_events(referrer_id,referral_date desc);create index if not exists idx_medical_referral_branch_date on public.medical_referral_events(branch_id,referral_date desc);alter table public.medical_referral_events enable row level security;
create index if not exists idx_operational_sales_customer_date on public.operational_sales(customer_id,sale_date desc);create index if not exists idx_operational_sales_demand on public.operational_sales(demand_request_id);create index if not exists idx_dispatches_demand on public.dispatches(demand_request_id);create index if not exists idx_clinical_demand_fulfilled_dispatch on public.clinical_demand_requests(fulfilled_dispatch_id);
-- Policies are finalized in the access-hardening migration below.
create or replace view public.vw_service_level_performance with (security_invoker=true) as select d.id demand_request_id,d.branch_id,d.customer_id,c.name customer_name,d.product_id,d.requested_units,d.requested_at,d.needed_by,d.priority,d.status,coalesce(d.fulfilled_dispatch_id,dp.id) dispatch_id,coalesce(d.fulfilled_at,dp.confirmed_at) fulfilled_at,case when coalesce(d.fulfilled_at,dp.confirmed_at) is null then null else round(extract(epoch from (coalesce(d.fulfilled_at,dp.confirmed_at)-d.requested_at))/60.0,1) end response_minutes,case when coalesce(d.fulfilled_at,dp.confirmed_at) is null then 'PENDIENTE' when d.needed_by is null then 'SIN_OBJETIVO' when coalesce(d.fulfilled_at,dp.confirmed_at)<=d.needed_by then 'A_TIEMPO' else 'FUERA_SLA' end sla_status,case when d.needed_by is null then null else round(extract(epoch from (d.needed_by-d.requested_at))/60.0,1) end target_minutes from public.clinical_demand_requests d left join public.customers c on c.id=d.customer_id left join lateral(select x.id,x.confirmed_at,x.created_at from public.dispatches x where x.demand_request_id=d.id order by x.confirmed_at desc nulls last,x.created_at desc limit 1) dp on true;
create or replace view public.vw_accounts_receivable with (security_invoker=true) as select s.id sale_id,s.sale_code,s.sale_date,coalesce(s.invoice_date,s.sale_date) invoice_date,s.payment_due_date,s.branch_id,s.customer_id,coalesce(c.name,s.customer_name) customer_name,s.invoice_number,s.total_amount,coalesce((select sum(p.amount) from public.customer_payments p where p.sale_id=s.id),s.collected_amount,0) paid_amount,greatest(s.total_amount-coalesce((select sum(p.amount) from public.customer_payments p where p.sale_id=s.id),s.collected_amount,0),0) outstanding_amount,greatest(current_date-coalesce(s.payment_due_date,coalesce(s.invoice_date,s.sale_date)+30),0) days_past_due,case when greatest(s.total_amount-coalesce((select sum(p.amount) from public.customer_payments p where p.sale_id=s.id),s.collected_amount,0),0)<=0 then 'PAGADA' when current_date<=coalesce(s.payment_due_date,coalesce(s.invoice_date,s.sale_date)+30) then 'VIGENTE' when current_date-coalesce(s.payment_due_date,coalesce(s.invoice_date,s.sale_date)+30)<=30 then '1-30' when current_date-coalesce(s.payment_due_date,coalesce(s.invoice_date,s.sale_date)+30)<=60 then '31-60' when current_date-coalesce(s.payment_due_date,coalesce(s.invoice_date,s.sale_date)+30)<=90 then '61-90' else '>90' end aging_bucket from public.operational_sales s left join public.customers c on c.id=s.customer_id where s.status is distinct from 'CANCELADA';
create or replace view public.vw_inventory_loss_economics with (security_invoker=true) as select branch_id,date_trunc('month',event_date)::date period_month,loss_type,count(*) events,sum(quantity) quantity,sum(estimated_loss) estimated_loss from public.inventory_loss_events group by branch_id,date_trunc('month',event_date)::date,loss_type;
create or replace view public.vw_campaign_economics with (security_invoker=true) as select c.*,coalesce(x.donations_captured,0) donations_captured,case when c.actual_cost>0 and coalesce(x.donations_captured,0)>0 then round(c.actual_cost/x.donations_captured,2) end cost_per_donation,case when c.contacts_reached>0 then round(100.0*coalesce(x.donations_captured,0)/c.contacts_reached,1) end contact_to_donation_pct from public.donor_campaigns c left join lateral(select count(*) donations_captured from public.donations d where d.campaign_id=c.id)x on true;
create or replace view public.vw_medical_network_performance with (security_invoker=true) as select r.id referrer_id,r.branch_id,r.referrer_code,r.full_name,r.specialty,r.organization,r.status,count(e.id) referrals,count(e.id) filter(where e.status='CONVERTIDO') converted_referrals,sum(e.estimated_units) estimated_units,case when count(e.id)>0 then round(100.0*count(e.id) filter(where e.status='CONVERTIDO')/count(e.id),1) end conversion_pct,max(e.referral_date) last_referral_date from public.medical_referrers r left join public.medical_referral_events e on e.referrer_id=r.id group by r.id,r.branch_id,r.referrer_code,r.full_name,r.specialty,r.organization,r.status;
grant select on public.vw_service_level_performance,public.vw_accounts_receivable,public.vw_inventory_loss_economics,public.vw_campaign_economics,public.vw_medical_network_performance to authenticated;
